import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { cn } from '@/lib/utils';
import { ContractDetails } from '../types/contractDetails.types';


function getStatusUi(statusRaw: string | null | undefined) {
    const s = String(statusRaw || '').toLowerCase().trim();
    if (s === 'active') return { label: 'ساري', className: 'bg-[#22AD5C] text-white-blue-50' };
    if (s === 'inactive') return { label: 'غير نشط', className: 'bg-[#FBB90D] text-primery-blue-900' };
    if (s === 'stopped') return { label: 'موقوف', className: 'bg-red-error-600 text-white-blue-50' };
    return { label: statusRaw || '—', className: 'bg-white-blue-300 text-primery-blue-900' };
}

function LabelValueRow({ label, value }: { label: string; value: React.ReactNode }) {
    return (
        <div className="flex flex-row items-center border-b border-b-white-blue-500">
            <p className="min-w-32 bg-white-blue-100 px-4 py-4 text-sm text-primery-blue-500 font-semibold tracking-normal leading-6 w-[128px]">
                {label}
            </p>
            <div className="flex flex-row items-center gap-4 p-2 w-full text-primery-blue-900 text-base font-medium">
                {value}
            </div>
        </div>
    );
}

export default function ContractDetailsPage() {
    const { id } = useParams();
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const shouldPrint = searchParams.get('print') === '1';

    const [loading, setLoading] = useState(true);
    const [data, setData] = useState<ContractDetails | null>(null);
    const [error, setError] = useState<string | null>(null);

    const contractId = useMemo(() => Number(id), [id]);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            if (!contractId || Number.isNaN(contractId)) {
                setError('رقم العقد غير صحيح');
                setLoading(false);
                return;
            }
            setLoading(true);
            setError(null);
            try {
                const res = await apiGet<{ data: ContractDetails }>({
                    endpoint: endpoints.hrContract.show + contractId,
                });
                if (!cancelled) setData(res.data.data);
            } catch {
                if (!cancelled) setError('تعذر تحميل بيانات العقد');
            } finally {
                if (!cancelled) setLoading(false);
            }
        };
        load();
        return () => {
            cancelled = true;
        };
    }, [contractId]);

    useEffect(() => {
        if (!loading && shouldPrint) {
            window.print();
        }
    }, [loading, shouldPrint]);

    const statusUi = getStatusUi(data?.status);

    return (
        <div className="w-full mt-6 mb-20">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between mb-6">
                <div className="flex items-center gap-3">
                    <UnderlineHeading text="تفاصيل العقد" />
                    {!loading ? (
                        <span className={cn('text-xs font-semibold px-2 py-1 rounded-sm', statusUi.className)}>
                            {statusUi.label}
                        </span>
                    ) : null}
                </div>
                <div className="flex flex-wrap gap-3 justify-start sm:justify-end">
                    <SecondaryButton type="button" onClick={() => navigate('/human-resources/contract-management')}>
                        رجوع
                    </SecondaryButton>
                    <SecondaryButton
                        type="button"
                        onClick={() => navigate(`/human-resources/contract-management/${contractId}?print=1`)}
                        disabled={loading || !data}
                    >
                        طباعة
                    </SecondaryButton>
                    {data?.file ? (
                        <PrimaryButton type="button" onClick={() => window.open(data.file as string, '_blank')}>
                            فتح ملف العقد
                        </PrimaryButton>
                    ) : null}
                </div>
            </div>

            {loading ? <p className="text-sm text-[#625E74]">جاري التحميل…</p> : null}
            {error ? <p className="text-sm text-red-600">{error}</p> : null}

            {!loading && !error && data ? (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div className="lg:col-span-2">
                        <div className="rounded-lg border border-[#E8E7EA] bg-white shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
                            <div className="p-4 border-b border-[#E8E7EA]">
                                <UnderlineHeading text="معلومات العقد" className="text-[18px] leading-[28px]" />
                            </div>
                            <div className="p-4">
                                <LabelValueRow label="الموظف" value={data.employee?.name || '—'} />
                                {/* <LabelValueRow label="كود الموظف" value={data.employee_number || '—'} /> */}
                                <LabelValueRow label="المسمى الوظيفي" value={data.employee?.position || '—'} />
                                <LabelValueRow
                                    label="نوع العمل"
                                    value={
                                        data.contract_type === 'full_time'
                                            ? 'دوام كامل'
                                            : data.contract_type === 'part_time'
                                              ? 'دوام جزئي'
                                              : data.contract_type || '—'
                                    }
                                />
                                <LabelValueRow label="تاريخ البدء" value={data.start_date || '—'} />
                                <LabelValueRow label="تاريخ التوقيع" value={data.sign_date || '—'} />
                                <LabelValueRow label="تاريخ الالتحاق" value={data.join_date || '—'} />
                                <LabelValueRow
                                    label="تاريخ الانتهاء"
                                    value={
                                        data.end_date ||
                                        (data.end_month || data.end_year ? `${data.end_month || '—'} / ${data.end_year || '—'}` : '—')
                                    }
                                />
                                <LabelValueRow label="الوصف" value={data.description || '—'} />
                            </div>
                        </div>
                    </div>

                    <div className="lg:col-span-1">
                        <div className="rounded-lg border border-[#E8E7EA] bg-white shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
                            <div className="p-4 border-b border-[#E8E7EA]">
                                <UnderlineHeading text="الراتب والبدلات" className="text-[18px] leading-[28px]" />
                            </div>
                            <div className="p-4 space-y-3">
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-white-blue-800">الراتب</span>
                                    <span className="text-primery-blue-900 font-semibold">
                                        {data.salary !== null && data.salary !== undefined ? String(data.salary) : '—'} {data.currency || ''}
                                    </span>
                                </div>
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-white-blue-800">دورة القبض</span>
                                    <span className="text-primery-blue-900 font-semibold">{data.salary_cycle || '—'}</span>
                                </div>
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-white-blue-800">الساعة الإضافية</span>
                                    <span className="text-primery-blue-900 font-semibold">
                                        {data.overtime_rate !== null && data.overtime_rate !== undefined ? String(data.overtime_rate) : '—'}
                                    </span>
                                </div>
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-white-blue-800">بدل السكن</span>
                                    <span className="text-primery-blue-900 font-semibold">
                                        {data.housing_allowance !== null && data.housing_allowance !== undefined
                                            ? String(data.housing_allowance)
                                            : '—'}
                                    </span>
                                </div>
                                <div className="flex items-center justify-between text-sm">
                                    <span className="text-white-blue-800">بدل المواصلات</span>
                                    <span className="text-primery-blue-900 font-semibold">
                                        {data.transportation_allowance !== null && data.transportation_allowance !== undefined
                                            ? String(data.transportation_allowance)
                                            : '—'}
                                    </span>
                                </div>
                            </div>
                        </div>

                        <div className="mt-6 rounded-lg border border-[#E8E7EA] bg-white shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
                            <div className="p-4 border-b border-[#E8E7EA]">
                                <UnderlineHeading text="ملف العقد" className="text-[18px] leading-[28px]" />
                            </div>
                            <div className="p-4">
                                {data.file ? (
                                    <div className="flex flex-col gap-3">
                                        <p className="text-sm text-[#625E74]">
                                            يمكنك فتح ملف العقد أو تحميله أو طباعته.
                                        </p>
                                        <div className="flex flex-wrap gap-3">
                                            <PrimaryButton type="button" onClick={() => window.open(data.file as string, '_blank')}>
                                                فتح
                                            </PrimaryButton>
                                            <SecondaryButton
                                                type="button"
                                                onClick={() => {
                                                    const a = document.createElement('a');
                                                    a.href = data.file as string;
                                                    a.target = '_blank';
                                                    a.rel = 'noreferrer';
                                                    a.click();
                                                }}
                                            >
                                                تحميل
                                            </SecondaryButton>
                                        </div>
                                    </div>
                                ) : (
                                    <p className="text-sm text-[#625E74]">لا يوجد ملف مرفق لهذا العقد.</p>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            ) : null}
        </div>
    );
}

